package pe.com.dentalamericana.treatment;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="plan_tratamiento_items")public class TreatmentItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="plan_id",nullable=false)private Long planId;@Column(name="servicio_id",nullable=false)private Long serviceId;private String pieza;@Column(nullable=false)private String descripcion;@Column(nullable=false)private int cantidad;@Column(name="precio_unitario",nullable=false)private BigDecimal unitPrice;@Column(nullable=false)private int sesiones;@Enumerated(EnumType.STRING)@Column(nullable=false)private TreatmentItemStatus estado;@Column(nullable=false)private boolean activo=true;@Column(name="creado_por",nullable=false)private Long createdBy;@Column(name="actualizado_por",nullable=false)private Long updatedBy;@Column(name="creado_en",nullable=false)private Instant createdAt;@Column(name="actualizado_en",nullable=false)private Instant updatedAt;@Version private Long version;protected TreatmentItem(){}public TreatmentItem(Long planId,Long serviceId,String tooth,String description,int quantity,BigDecimal unitPrice,int sessions,Long actor){this.planId=planId;this.serviceId=serviceId;this.pieza=tooth;this.descripcion=description;this.cantidad=quantity;this.unitPrice=unitPrice;this.sesiones=sessions;this.estado=TreatmentItemStatus.PROPUESTO;this.createdBy=actor;this.updatedBy=actor;}public BigDecimal subtotal(){return unitPrice.multiply(BigDecimal.valueOf(cantidad));}public void changeStatus(TreatmentItemStatus status,Long actor){this.estado=status;this.updatedBy=actor;}public void deactivate(Long actor){activo=false;updatedBy=actor;}@PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public Long getPlanId(){return planId;}public Long getServiceId(){return serviceId;}public String getTooth(){return pieza;}public String getDescription(){return descripcion;}public int getQuantity(){return cantidad;}public BigDecimal getUnitPrice(){return unitPrice;}public int getSessions(){return sesiones;}public TreatmentItemStatus getStatus(){return estado;}public Instant getCreatedAt(){return createdAt;}public Long getVersion(){return version;}}
